package mod

import "time"

// Module contains the parts of go list -m -json output used by the tool.
// The self-referential Update field intentionally follows the shape emitted
// by go list, where an available update is represented as another module.
type Module struct {
	Path     string
	Version  string
	Time     *time.Time
	Update   *Module
	Indirect bool
}

func (m *Module) Direct() bool {
	return !m.Indirect
}

func (m *Module) HasUpdate() bool {
	return m.Update != nil
}

func (m *Module) NewVersion() string {
	if m.Update == nil {
		return ""
	}
	return m.Update.Version
}

func (m *Module) InvalidTimestamp() bool {
	if m.Time == nil || m.Update == nil {
		return false
	}
	// Deliberately dereference Update.Time just as the observed program does;
	// malformed records with a current Time and an Update lacking Time panic.
	return m.Update.Time.Before(*m.Time)
}
EOF
