package runner

import (
	"encoding/json"
	"io"
	"strconv"

	"github.com/psampaz/go-mod-outdated/internal/mod"
	"github.com/psampaz/go-mod-outdated/internal/table"
)

func Run(in io.Reader, out io.Writer, updateOnly bool, directOnly bool, ci bool, style string) (int, error) {
	mods, err := readModules(in)
	if err != nil {
		return 0, err
	}

	filtered := make([]mod.Module, 0, len(mods))
	for _, module := range mods {
		if updateOnly && !module.HasUpdate() {
			continue
		}
		if directOnly && !module.Direct() {
			continue
		}
		filtered = append(filtered, module)
	}

	renderTable(out, filtered, style)

	if ci {
		for i := range filtered {
			if filtered[i].HasUpdate() {
				return 1, nil
			}
		}
	}
	return 0, nil
}

func readModules(in io.Reader) ([]mod.Module, error) {
	decoder := json.NewDecoder(in)
	modules := make([]mod.Module, 0)
	for {
		var module mod.Module
		err := decoder.Decode(&module)
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		modules = append(modules, module)
	}
	return modules, nil
}

func renderTable(out io.Writer, modules []mod.Module, style string) {
	if len(modules) == 0 {
		return
	}

	rows := make([][]string, 0, len(modules))
	for i := range modules {
		module := &modules[i]
		rows = append(rows, []string{
			module.Path,
			module.Version,
			module.NewVersion(),
			strconv.FormatBool(module.Direct()),
			strconv.FormatBool(!module.InvalidTimestamp()),
		})
	}

	t := table.New([]string{"MODULE", "VERSION", "NEW VERSION", "DIRECT", "VALID TIMESTAMPS"}, rows)
	if style == "markdown" {
		t.RenderMarkdown(out)
		return
	}
	t.RenderDefault(out)
}
EOF
cat > internal/table/table.go <<'EOF'
package table

import (
	"fmt"
	"io"
	"regexp"
	"strings"
)

var numericRE = regexp.MustCompile(`^-?[0-9][0-9.,]*$`)

type Table struct {
	headers []string
	rows    [][]string
	widths  []int
}

func New(headers []string, rows [][]string) *Table {
	t := &Table{headers: headers, rows: rows, widths: make([]int, len(headers))}
	for i, h := range headers {
		t.widths[i] = displayWidth(h)
	}
	for _, row := range rows {
		for i := range headers {
			cell := ""
			if i < len(row) {
				cell = row[i]
			}
			for _, line := range splitLines(cell) {
				if w := displayWidth(line); w > t.widths[i] {
					t.widths[i] = w
				}
			}
		}
	}
	return t
}

func (t *Table) RenderDefault(out io.Writer) {
	fmt.Fprintln(out, t.borderLine('+'))
	fmt.Fprintln(out, t.headerLine())
	fmt.Fprintln(out, t.borderLine('+'))
	for _, row := range t.rows {
		for _, line := range t.rowLines(row) {
			fmt.Fprintln(out, line)
		}
	}
	fmt.Fprintln(out, t.borderLine('+'))
}

func (t *Table) RenderMarkdown(out io.Writer) {
	fmt.Fprintln(out, t.headerLine())
	fmt.Fprintln(out, t.markdownSeparator())
	for _, row := range t.rows {
		for _, line := range t.rowLines(row) {
			fmt.Fprintln(out, line)
		}
	}
}

func (t *Table) borderLine(sep rune) string {
	var b strings.Builder
	b.WriteRune(sep)
	for _, w := range t.widths {
		b.WriteString(strings.Repeat("-", w+2))
		b.WriteRune(sep)
	}
	return b.String()
}

func (t *Table) markdownSeparator() string {
	var b strings.Builder
	b.WriteByte('|')
	for _, w := range t.widths {
		b.WriteString(strings.Repeat("-", w+2))
		b.WriteByte('|')
	}
	return b.String()
}

func (t *Table) headerLine() string {
	var b strings.Builder
	b.WriteByte('|')
	for i, h := range t.headers {
		b.WriteString(center(h, t.widths[i]+2))
		b.WriteByte('|')
	}
	return b.String()
}

func (t *Table) rowLines(row []string) []string {
	parts := make([][]string, len(t.headers))
	maxLines := 1
	for i := range t.headers {
		cell := ""
		if i < len(row) {
			cell = row[i]
		}
		parts[i] = splitLines(cell)
		if len(parts[i]) > maxLines {
			maxLines = len(parts[i])
		}
	}

	lines := make([]string, 0, maxLines)
	for lineNo := 0; lineNo < maxLines; lineNo++ {
		var b strings.Builder
		b.WriteByte('|')
		for i := range t.headers {
			cell := ""
			if lineNo < len(parts[i]) {
				cell = parts[i][lineNo]
			}
			if isNumeric(cell) {
				b.WriteString(right(cell, t.widths[i]+2))
			} else {
				b.WriteString(left(cell, t.widths[i]+2))
			}
			b.WriteByte('|')
		}
		lines = append(lines, b.String())
	}
	return lines
}

func splitLines(s string) []string {
	parts := strings.Split(s, "\n")
	if len(parts) == 0 {
		return []string{""}
	}
	return parts
}

func displayWidth(s string) int {
	// Go module paths and versions are ASCII. Counting runes instead of bytes
	// avoids surprising width inflation for non-ASCII input while preserving the
	// observed behavior for the benchmark's normal data.
	return len([]rune(s))
}

func center(s string, width int) string {
	w := displayWidth(s)
	if w >= width {
		return s
	}
	diff := width - w
	leftPad := diff / 2
	rightPad := diff - leftPad
	return strings.Repeat(" ", leftPad) + s + strings.Repeat(" ", rightPad)
}

func left(s string, width int) string {
	w := displayWidth(s)
	if w >= width {
		return s
	}
	return " " + s + strings.Repeat(" ", width-w-1)
}

func right(s string, width int) string {
	w := displayWidth(s)
	if w >= width {
		return s
	}
	return strings.Repeat(" ", width-w-1) + s + " "
}

func isNumeric(s string) bool {
	return numericRE.MatchString(s)
}
EOF
