func (t *Table) RenderDefault(out io.Writer) {
	fmt.Fprintln(out, t.borderLine('+'))
	fmt.Fprintln(out, t.headerLine())
	fmt.Fprintln(out, t.borderLine('+'))
	for _, row := range t.rows {
		for _, line := range t.rowLines(row) {
			fmt.Fprintln(out, line)
		}
	}
	fmt.Fprintln(out, t.borderLine('+'))
}

func (t *Table) RenderMarkdown(out io.Writer) {
	fmt.Fprintln(out, t.headerLine())
	fmt.Fprintln(out, t.markdownSeparator())
	for _, row := range t.rows {
		for _, line := range t.rowLines(row) {
			fmt.Fprintln(out, line)
		}
	}
}

func (t *Table) borderLine(sep rune) string {
	var b strings.Builder
	b.WriteRune(sep)
	for _, w := range t.widths {
		b.WriteString(strings.Repeat("-", w+2))
		b.WriteRune(sep)
	}
	return b.String()
}

func (t *Table) markdownSeparator() string {
	var b strings.Builder
	b.WriteByte('|')
	for _, w := range t.widths {
		b.WriteString(strings.Repeat("-", w+2))
		b.WriteByte('|')
	}
	return b.String()
}

func (t *Table) headerLine() string {
	var b strings.Builder
	b.WriteByte('|')
	for i, h := range t.headers {
		b.WriteString(center(h, t.widths[i]+2))
		b.WriteByte('|')
	}
	return b.String()
}

func (t *Table) rowLines(row []string) []string {
	parts := make([][]string, len(t.headers))
	maxLines := 1
	for i := range t.headers {
		cell := ""
		if i < len(row) {
			cell = row[i]
		}
		parts[i] = splitLines(cell)
		if len(parts[i]) > maxLines {
			maxLines = len(parts[i])
		}
	}

	lines := make([]string, 0, maxLines)
	for lineNo := 0; lineNo < maxLines; lineNo++ {
		var b strings.Builder
		b.WriteByte('|')
		for i := range t.headers {
			cell := ""
			if lineNo < len(parts[i]) {
				cell = parts[i][lineNo]
			}
			if isNumeric(cell) {
				b.WriteString(right(cell, t.widths[i]+2))
			} else {
				b.WriteString(left(cell, t.widths[i]+2))
			}
			b.WriteByte('|')
		}
		lines = append(lines, b.String())
	}
	return lines
}

func splitLines(s string) []string {
	parts := strings.Split(s, "\n")
	if len(parts) == 0 {
		return []string{""}
	}
	return parts
}

func displayWidth(s string) int {
	// Go module paths and versions are ASCII. Counting runes instead of bytes
	// avoids surprising width inflation for non-ASCII input while preserving the
	// observed behavior for the benchmark's normal data.
	return len([]rune(s))
}

func center(s string, width int) string {
	w := displayWidth(s)
	if w >= width {
		return s
	}
	diff := width - w
	leftPad := diff / 2
	rightPad := diff - leftPad
	return strings.Repeat(" ", leftPad) + s + strings.Repeat(" ", rightPad)
}

func left(s string, width int) string {
	w := displayWidth(s)
	if w >= width {
		return s
	}
	return " " + s + strings.Repeat(" ", width-w-1)
}

func right(s string, width int) string {
	w := displayWidth(s)
	if w >= width {
		return s
	}
	return strings.Repeat(" ", width-w-1) + s + " "
}

func isNumeric(s string) bool {
	return numericRE.MatchString(s)
}
